namespace Nomax.SharedKernel.Identifiers;

/// <summary>
/// Primary keys are UUIDv7 generated by the application (docs/03 §1, D-07): time-ordered, so B-tree indexes stay compact.
/// The exception is identity.user_profiles.id, which equals the Keycloak <c>sub</c>.
/// </summary>
public static class Uuid7
{
    public static Guid New(TimeProvider timeProvider)
    {
        ArgumentNullException.ThrowIfNull(timeProvider);
        return Guid.CreateVersion7(timeProvider.GetUtcNow());
    }
}
